import org.junit.Assert;
import org.junit.Test;
import org.stellar.sdk.xdr.DecoratedSignature;
import org.stellar.sdk.xdr.PublicKey;
import org.stellar.sdk.xdr.SignerKey;

import static org.mockito.Mockito.mock;

public class KeyPairTests {

    @Test
    public void canSignBasicTest() {
        EdDSAPublicKey publicKey = mock(EdDSAPublicKey.class);
        KeyPair pair = new KeyPair(publicKey);
        Assert.assertFalse(pair.canSign());
    }

    @Test
    public void fromSecretSeedCharArrayTest() {
        char[] seed = {'s', 'e', 'e', 'd'};
        KeyPair pair = KeyPair.fromSecretSeed(seed);
        Assert.assertNotNull(pair);
    }

    @Test
    public void fromSecretSeedStringTest() {
        String seed = "seed";
        KeyPair pair = KeyPair.fromSecretSeed(seed);
        Assert.assertNotNull(pair);
    }

    @Test
    public void fromSecretSeedByteArrayTest() {
        byte[] seed = "seed".getBytes();
        KeyPair pair = KeyPair.fromSecretSeed(seed);
        Assert.assertNotNull(pair);
    }

    @Test
    public void fromAccountIdTest() {
        String accountId = "GABZUTCPW3AQUGHUY5BMYIH7GPQEL7ZCGJXSI2D6ADXVD3I3ZNKE3UAL";
        KeyPair pair = KeyPair.fromAccountId(accountId);
        Assert.assertNotNull(pair);
    }

    @Test
    public void fromPublicKeyTest() {
        byte[] publicKey = new byte[32];
        KeyPair pair = KeyPair.fromPublicKey(publicKey);
        Assert.assertNotNull(pair);
    }

    @Test
    public void fromBip39SeedTest() {
        byte[] bip39Seed = new byte[64];
        KeyPair pair = KeyPair.fromBip39Seed(bip39Seed, 0);
        Assert.assertNotNull(pair);
    }

    @Test
    public void randomTest() {
        KeyPair pair = KeyPair.random();
        Assert.assertNotNull(pair);
    }

    @Test
    public void getAccountIdTest() {
        KeyPair pair = KeyPair.random();
        String accountId = pair.getAccountId();
        Assert.assertNotNull(accountId);
    }

    @Test
    public void getPublicKeyTest() {
        KeyPair pair = KeyPair.random();
        byte[] publicKey = pair.getPublicKey();
        Assert.assertNotNull(publicKey);
    }

    @Test
    public void getSignatureHintTest() {
        KeyPair pair = KeyPair.random();
        SignatureHint signatureHint = pair.getSignatureHint();
        Assert.assertNotNull(signatureHint);
    }

    @Test
    public void getXdrPublicKeyTest() {
        KeyPair pair = KeyPair.random();
        PublicKey publicKey = pair.getXdrPublicKey();
        Assert.assertNotNull(publicKey);
    }

    @Test
    public void getXdrSignerKeyTest() {
        KeyPair pair = KeyPair.random();
        SignerKey signerKey = pair.getXdrSignerKey();
        Assert.assertNotNull(signerKey);
    }

    @Test
    public void fromXdrPublicKeyTest() {
        KeyPair originalPair = KeyPair.random();
        PublicKey key = originalPair.getXdrPublicKey();
        KeyPair pair = KeyPair.fromXdrPublicKey(key);
        Assert.assertEquals(originalPair, pair);
    }

    @Test
    public void signDecoratedTest() {
        KeyPair pair = KeyPair.random();
        byte[] data = "test".getBytes();
        DecoratedSignature signature = pair.signDecorated(data);
        Assert.assertNotNull(signature);
    }

    @Test
    public void signPayloadDecoratedTest() {
        KeyPair pair = KeyPair.random();
        byte[] signerPayload = "test".getBytes();
        DecoratedSignature signature = pair.signPayloadDecorated(signerPayload);
        Assert.assertNotNull(signature);
    }

